var generateXmlSitemap = (domain, regions, services) => {
	const baseUrl = domain.replace(/\/$/, "");
	const now = (/* @__PURE__ */ new Date()).toISOString().split("T")[0];
	const urls = [{
		loc: `${baseUrl}/`,
		priority: "1.0",
		changefreq: "daily"
	}];
	services.forEach((s) => {
		const sInfo = SERVICE_URL_MAP[s.id];
		const slug = sInfo ? sInfo.slug : s.id;
		urls.push({
			loc: `${baseUrl}/service/${slug}`,
			priority: "0.9",
			changefreq: "weekly"
		});
	});
	regions.forEach((r) => {
		const rInfo = REGION_URL_MAP[r];
		const slug = rInfo ? rInfo.slug : r;
		urls.push({
			loc: `${baseUrl}/region/${slug}`,
			priority: "0.8",
			changefreq: "weekly"
		});
	});
	regions.forEach((r) => {
		const rInfo = REGION_URL_MAP[r];
		const rSlug = rInfo ? rInfo.slug : r;
		services.forEach((s) => {
			const sInfo = SERVICE_URL_MAP[s.id];
			const sSlug = sInfo ? sInfo.slug : s.id;
			urls.push({
				loc: `${baseUrl}/region/${rSlug}/service/${sSlug}`,
				priority: "0.7",
				changefreq: "monthly"
			});
		});
	});
	let xml = `<?xml version="1.0" encoding="UTF-8"?>\n`;
	xml += `<urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">\n`;
	urls.forEach((u) => {
		xml += `  <url>\n`;
		xml += `    <loc>${u.loc}</loc>\n`;
		xml += `    <lastmod>${now}</lastmod>\n`;
		xml += `    <changefreq>${u.changefreq}</changefreq>\n`;
		xml += `    <priority>${u.priority}</priority>\n`;
		xml += `  </url>\n`;
	});
	xml += `</urlset>`;
	return xml;
};
